{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 ChronoWarp\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Creative Half-Time and Varispeed Engine with continuous ring-buffer time stretching, smooth windowing, dual bandpass filtering, and shimmer pitch layering.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Three speed modes: 1.5x (-5 semitones), 2x Half-Time (-1 octave), 4x Quarter-Time (-2 octaves)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Synchronized loop lengths from 1/16 up to 8 Bars\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Continuous Smooth contour control for percussion/FX vs sustain/swell\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Dual bandpass filtering (Low Cut & High Cut) with Band Solo mode\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Tempo-synced Fade In and Fade Out envelopes to eliminate clicks\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Forward and Reverse playback directions\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Upper-octave shimmer layer with blend control\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom (100% - 140%)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 VintageFlux\par}
{\pard \ql \f0 \sa180 \li0 \fi0 6-Module vintage texture, retro color, and lo-fi multi-effects workstation with global magnitude scaling and organic parameter flux.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 6 Dedicated Vintage FX Modules:\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab Noise: Vinyl, Cassette, VHS, and White noise with envelope following and ducking\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab Wobble: Pitch wow and flutter with rate and stereo drift\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab Distort: Tube, Tape, Crunch, and Wavefold saturation with focused frequency crossover\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab Digital: Sample rate downsampling and bitcrushing with smoothing and pass/cut options\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab Space: Ambient algorithmic reverb with pre-delay, decay, and damping controls\par}
{\pard \ql \f0 \sa0 \li720 \fi-360 \endash \tx360\tab Magnetic: Vintage tape wear, dropouts, and flutter imperfections\sa180\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Global Magnitude slider to scale all module intensities simultaneously\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Dedicated FLUX controls on every module for organic, non-repeating analog drift\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Master Section with 12/24 dB Low & High Cut filters, Tilt/Smile tone EQ, M/S Width, and Output Trim\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom (100% - 140%)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
