\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 EchoForge\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Analog Tape, Lo-Fi, and Diffused Delay workstation with modulation, distortion, bitcrushing, and 4-stage stereo all-pass diffusion.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 4 Delay Models: Mono, Stereo, Ping-Pong, and Off (standalone Lo-Fi / Modulation / Reverb FX processor)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Tempo-synced (1/16 to 1 bar) and free-running millisecond modes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Tape Pitch glide (authentic tape Doppler pitch slew) vs Keep Pitch (clickless time crossfading)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Self-oscillating feedback (up to 150%) tamed by analog-modeled tape saturation or limiter\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Resonant feedback filter with Low-Pass, High-Pass, and Band-Pass modes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 4-Stage Stereo All-Pass Diffusion engine for smearing repeats into lush ambient reverb washes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Lo-Fi degradation engine: variable sample rate downsampling and bit depth reduction\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Multi-destination modulation LFO targeting delay time and filter cutoff\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Output tilt tone EQ, stereo width spread, and independent dry/wet controls\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom (100% - 140%)\sa180\par}
}

