{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 PocketQ\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Compact, ultra-low CPU console channel strip equalizer with fixed musical frequencies, E/G curves, and high-headroom Air Band.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Fixed musical frequency bands: Sub (10 Hz), 40 Hz, 160 Hz, 650 Hz, and 2.5 kHz (switchable Shelf/Bell)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab High-headroom Air Band shelf with selectable frequencies (2.5k, 5k, 10k, 20k, 40 kHz)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 18 dB/oct HPF and 12 dB/oct LPF console cut filters\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab E-Series (tight constant Q) and G-Series (smooth proportional Q) response curves\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Console Drive switch with Clean and Warm analog saturation\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Auto-gain compensation and phase invert toggle\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Ultra-lightweight DSP footprint optimized for loading across every mixer track\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom (100% - 140%)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
