{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 OInflator\par}
{\pard \ql \f0 \sa180 \li0 \fi0 A high-precision polynomial waveshaper and harmonic loudness enhancer with multiband split processing.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Authentic polynomial transfer curve shaping\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Phase-compensated 3-band split processing (240 Hz / 2.4 kHz crossovers)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Curve control (-50 to +50) for fine harmonic balance\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Clip 0dB ceiling protection\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Calibrated studio peak and RMS metering with clip indicators\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Credits\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Core DSP algorithms by JClones (https://github.com/JClones/JSFXClones), licensed under MIT.\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Phoenix\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Analog Tape Saturator with 5 selectable tape saturation topologies and 3 high-frequency flux responses.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Features\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 5 selectable tape saturation topologies: Luminescent, Iridescent, Radiant, Luster, and Dark Essence\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab 3 high-frequency flux responses: Opal (Neutral), Gold (Warm), and Sapphire (Bright)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Input trim, process, and output trim controls\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Auto-gain compensation mode\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Calibrated studio peak and RMS metering with clip indicators\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Scalable HiDPI text zoom\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel2 \b \fs28 Credits\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Core DSP algorithms by JClones (https://github.com/JClones/JSFXClones), licensed under MIT.\sa180\par}
}

